package admissionproof

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"encoding/hex"
	"fmt"
	"os"
	"sort"
	"strings"
	"testing"
	"time"

	batchv1 "k8s.io/api/batch/v1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"sigs.k8s.io/controller-runtime/pkg/envtest"
)

// TestCanonicalMigrationCreateDefaults records the actual API-server response
// to the synthetic social/app-only request generated by migrations.documents
// and native_migrations_runtime.build_request at the pinned producer commit.
// The fixture SQL is synthetic and is never executed (envtest has no Job
// controller, database, or kubelet).
func TestCanonicalMigrationCreateDefaults(t *testing.T) {
	assets := os.Getenv("KUBEBUILDER_ASSETS")
	if assets == "" {
		t.Fatal("KUBEBUILDER_ASSETS must point at pinned Kubernetes v1.34.3 envtest binaries")
	}
	env := &envtest.Environment{BinaryAssetsDirectory: assets,
		ControlPlane: envtest.ControlPlane{APIServer: &envtest.APIServer{Args: []string{
			"--advertise-address=127.0.0.1", "--enable-admission-plugins=ValidatingAdmissionPolicy",
		}}}, ControlPlaneStartTimeout: 2 * time.Minute, ControlPlaneStopTimeout: 30 * time.Second}
	cfg, err := env.Start()
	if err != nil {
		t.Fatalf("start private Kubernetes API server: %v", err)
	}
	t.Cleanup(func() {
		if err := env.Stop(); err != nil {
			t.Errorf("stop private Kubernetes API server: %v", err)
		}
	})
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	client, err := kubernetes.NewForConfig(cfg)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := client.CoreV1().Namespaces().Create(ctx, namespaceObject("voice-staging"), metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}

	// Exact source-backed request fixture supplied by the migration producer.
	// SHA-256 below is over the literal UTF-8 SQL bytes.
	const sql = "CREATE TABLE example (id bigint);\n"
	const name = "voice-rollout-aaaaaaaaaaaa-social"
	const image = "migrate/migrate@sha256:f21c436af23c282f4516b00ba3e93bccf5c5fe5cd52530fd5c319a936998f539"
	const jobRequest = `{"apiVersion":"batch/v1","kind":"Job","metadata":{"name":"` + name + `","namespace":"voice-staging","labels":{"voice-rollout-operation":"aaaaaaaaaaaa","voice-rollout-database":"social"}},"spec":{"backoffLimit":0,"activeDeadlineSeconds":300,"template":{"metadata":{"labels":{"voice-rollout-operation":"aaaaaaaaaaaa","voice-rollout-database":"social"}},"spec":{"restartPolicy":"Never","automountServiceAccountToken":false,"securityContext":{"runAsNonRoot":true,"runAsUser":65532,"runAsGroup":65532},"containers":[{"name":"migrate","image":"` + image + `","args":["-path=/migrations","-database=$(DATABASE_URL)","up"],"env":[{"name":"DATABASE_URL","valueFrom":{"secretKeyRef":{"name":"voice-app-secrets","key":"SOCIAL_DATABASE_URL"}}}],"securityContext":{"allowPrivilegeEscalation":false,"readOnlyRootFilesystem":true,"capabilities":{"drop":["ALL"]}},"volumeMounts":[{"name":"migrations","mountPath":"/migrations","readOnly":true}]}],"volumes":[{"name":"migrations","configMap":{"name":"` + name + `","optional":false}}]}}}}`
	cmRequest := map[string]any{"apiVersion": "v1", "kind": "ConfigMap",
		"metadata": map[string]any{"name": name, "namespace": "voice-staging", "labels": map[string]any{
			"voice-rollout-operation": "aaaaaaaaaaaa", "voice-rollout-database": "social"}},
		"immutable": true, "data": map[string]any{"000001_example.up.sql": sql}}
	var jobRequestObject map[string]any
	if err := json.Unmarshal([]byte(jobRequest), &jobRequestObject); err != nil {
		t.Fatal(err)
	}
	requested := []map[string]any{cmRequest, jobRequestObject}
	observed := make([]map[string]any, 0, 2)
	for _, resource := range requested {
		encoded, err := json.Marshal(resource)
		if err != nil {
			t.Fatal(err)
		}
		var got map[string]any
		path := "/apis/batch/v1/namespaces/voice-staging/jobs/" + name
		if resource["kind"] == "ConfigMap" {
			path = "/api/v1/namespaces/voice-staging/configmaps/" + name
		}
		if resource["kind"] == "ConfigMap" {
			var obj struct {
				APIVersion string `json:"apiVersion"`
				Kind       string `json:"kind"`
				Metadata   metav1.ObjectMeta `json:"metadata"`
				Immutable  *bool `json:"immutable"`
				Data       map[string]string `json:"data"`
			}
			if err := json.Unmarshal(encoded, &obj); err != nil { t.Fatal(err) }
			configMap := coreConfigMap(obj)
			created, err := client.CoreV1().ConfigMaps("voice-staging").Create(ctx, &configMap, metav1.CreateOptions{})
			if err != nil { t.Fatalf("ConfigMap CREATE %s: %v", path, err) }
			got, err = toMap(created)
		} else {
			jobValue := batchJob(jobRequestObject)
			created, err := client.BatchV1().Jobs("voice-staging").Create(ctx, &jobValue, metav1.CreateOptions{})
			if err != nil { t.Fatalf("Job CREATE %s: %v", path, err) }
			got, err = toMap(created)
		}
		if err != nil { t.Fatal(err) }
		observed = append(observed, got)
		for _, line := range defaultDiff(resource, got) { t.Logf("DEFAULT %s", line) }
	}

	cm, job := observed[0], observed[1]
	cmMeta := cm["metadata"].(map[string]any)
	jobMeta := job["metadata"].(map[string]any)
	if cmMeta["uid"] == nil || cmMeta["resourceVersion"] == nil || jobMeta["uid"] == nil || jobMeta["resourceVersion"] == nil {
		t.Fatal("API did not assign resource identity")
	}
	jobSpec := job["spec"].(map[string]any)
	selector, ok := jobSpec["selector"].(map[string]any)
	if !ok { t.Fatalf("API did not generate Job selector: %#v", jobSpec["selector"]) }
	match := selector["matchLabels"].(map[string]any)
	for _, key := range []string{"batch.kubernetes.io/controller-uid", "batch.kubernetes.io/job-name"} {
		if match[key] == nil { t.Errorf("generated selector missing %s", key) }
	}
	template := jobSpec["template"].(map[string]any)
	labels := template["metadata"].(map[string]any)["labels"].(map[string]any)
	for key, value := range match {
		if labels[key] != value { t.Errorf("pod template generated label %s=%v does not match selector (%v)", key, labels[key], value) }
	}
	if jobSpec["podReplacementPolicy"] == nil { t.Error("API did not report podReplacementPolicy") }
	gotSpec := template["spec"].(map[string]any)
	for _, key := range []string{"restartPolicy", "dnsPolicy", "schedulerName", "terminationGracePeriodSeconds", "enableServiceLinks"} {
		if _, ok := gotSpec[key]; !ok { t.Errorf("API PodSpec response missing expected default field %q", key) }
	}
	// Ensure the request's security, command, image, references, and fixture data
	// survive API defaulting unchanged. Identity/default metadata is excluded.
	cmData := cm["data"].(map[string]any)
	if cm["immutable"] != true || cmData["000001_example.up.sql"] != sql { t.Fatal("ConfigMap content changed during CREATE") }
	containers := gotSpec["containers"].([]any)
	container := containers[0].(map[string]any)
	if container["image"] != image || !jsonEqual(container["args"], []any{"-path=/migrations", "-database=$(DATABASE_URL)", "up"}) {
		t.Fatalf("Job command/image changed during CREATE: image=%v args=%v", container["image"], container["args"])
	}
	t.Logf("FIXTURE sql_sha256=%s bytes=%d", sha256Hex(sql), len(sql))
	t.Logf("INVARIANTS ConfigMap immutable/data preserved; Job image/args/env/security/mounts preserved; selector controller UID and job-name labels match pod template; no Secret created",)
}

func namespaceObject(name string) *corev1.Namespace {
	return &corev1.Namespace{ObjectMeta: metav1.ObjectMeta{Name: name, Labels: map[string]string{"kubernetes.io/metadata.name": name}}}
}

func coreConfigMap(o struct { APIVersion string `json:"apiVersion"`; Kind string `json:"kind"`; Metadata metav1.ObjectMeta `json:"metadata"`; Immutable *bool `json:"immutable"`; Data map[string]string `json:"data"` }) corev1.ConfigMap {
	return corev1.ConfigMap{TypeMeta: metav1.TypeMeta{APIVersion:o.APIVersion,Kind:o.Kind}, ObjectMeta:o.Metadata, Immutable:o.Immutable, Data:o.Data}
}

func batchJob(o map[string]any) batchv1.Job { b,_:=json.Marshal(o); var v batchv1.Job; _=json.Unmarshal(b,&v); return v }

func toMap(value any) (map[string]any, error) { b,err:=json.Marshal(value); if err!=nil{return nil,err}; var out map[string]any; err=json.Unmarshal(b,&out); return out,err }

func defaultDiff(want, got any) []string {
	var rows []string
	var walk func(string, any, any)
	walk = func(path string, a, b any) {
		am, aok := a.(map[string]any); bm, bok := b.(map[string]any)
		if aok && bok {
			keys:=map[string]bool{}; for k:=range am {keys[k]=true}; for k:=range bm {keys[k]=true}
			ordered:=make([]string,0,len(keys)); for k:=range keys {ordered=append(ordered,k)}; sort.Strings(ordered)
			for _,k:=range ordered {av,aHas:=am[k]; bv,bHas:=bm[k]; p:=path+"."+k; if !aHas {rows=append(rows,fmt.Sprintf("%s absent -> %T %s",p,bv,knownValue(p,bv))); continue}; if !bHas {rows=append(rows,fmt.Sprintf("%s %T removed",p,av)); continue}; walk(p,av,bv)}
			return
		}
		if !jsonEqual(a,b) { rows=append(rows,fmt.Sprintf("%s %T %s -> %T %s",path,a,knownValue(path,a),b,knownValue(path,b))) }
	}
	walk("$",want,got); sort.Strings(rows); return rows
}

func knownValue(path string, value any) string {
	if strings.HasSuffix(path,".uid") { return "<generated-uid>" }
	if strings.HasSuffix(path,".resourceVersion") { return "<generated-rv>" }
	b,_:=json.Marshal(value); return string(b)
}

func jsonEqual(a, b any) bool { return fmt.Sprint(mustJSON(a)) == fmt.Sprint(mustJSON(b)) }
func mustJSON(value any) []byte { b, _ := json.Marshal(value); return b }
func sha256Hex(value string) string { sum := sha256.Sum256([]byte(value)); return hex.EncodeToString(sum[:]) }

